import {
  Column,
  CreateDateColumn,
  Entity,
  JoinColumn,
  ManyToOne,
  OneToMany,
  PrimaryColumn,
} from 'typeorm';
import { Exercise } from '@modules/catalog/entities/exercise.entity';
import { WorkoutSet } from './workout-set.entity';

@Entity({ name: 'workout_entries' })
export class WorkoutEntry {
  // Not generated by TypeORM: the write flow assigns UUIDv7 ids itself (see SCHEMA.md).
  @PrimaryColumn({ name: 'id', type: 'uuid' })
  id!: string;

  @Column({ name: 'user_id', type: 'text' })
  userId!: string;

  @Column({ name: 'exercise_id', type: 'int' })
  exerciseId!: number;

  @ManyToOne(() => Exercise, { onDelete: 'RESTRICT' })
  @JoinColumn({ name: 'exercise_id' })
  exercise!: Exercise;

  @Column({ name: 'performed_on', type: 'date' })
  performedOn!: string;

  @CreateDateColumn({ name: 'created_at', type: 'timestamptz' })
  createdAt!: Date;

  @OneToMany(() => WorkoutSet, (set) => set.entry)
  sets!: WorkoutSet[];
}
